USE `RestaurantMS`;
-- 创建视图：厨师及其制作的菜品
CREATE  OR REPLACE VIEW ChefDishesView AS
SELECT 
    e.EmployeeID,
    e.EmployeeName AS ChefName,
    mi.MenuItemID,
    mi.Name AS DishName,
    mi.Price,
    COUNT(omc.OrderID) AS TimesCooked,
    GROUP_CONCAT(DISTINCT o.Customer) AS Customers
FROM Employee e
JOIN OrderMenuItemCooker omc ON e.EmployeeID = omc.CookerID
JOIN MenuItem mi ON omc.MenuItemID = mi.MenuItemID
JOIN Orders o ON omc.OrderID = o.OrderID
WHERE e.Position = 'COOKER'
GROUP BY e.EmployeeID, mi.MenuItemID;
USE `RestaurantMS`;

