CREATE TRIGGER `CheckCookerPositionT` 
BEFORE INSERT ON `OrderMenuItemCooker` 
FOR EACH ROW 
BEGIN
    DECLARE employee_position VARCHAR(45);

    -- 获取 CookerID 对应的职位
    SELECT Position 
    INTO employee_position
    FROM Employee 
    WHERE EmployeeID = NEW.CookerID
